const valueClassName = 'ms-auto shrink-0 font-normal text-neutral-600 text-xs tabular-nums';
// A caption is a sentence and can outrun a narrow row, so it truncates rather than pushing out.
const captionClassName = 'ms-auto min-w-0 truncate font-normal text-neutral-600 text-xs';

