                inline: 'm-[2px] rounded-[calc(var(--radius-control)-3px)] px-2',
                // The bar's own 3px inset already holds it, so it takes the buttons' size and corner.
                floating: 'rounded-[calc(var(--radius-control)-4px)] px-2.5',
