var one = (value) => Number(value.toFixed(1));
var log = (lines) => `log\u2082 ${one(lines)}`;
var getSpacingTool = defineTool({
  name: "get_spacing",
  title: "Get spacing",
  description: "Works out one padding or gap with Continuum's spacing formula and snaps it to a Tailwind step: returns { px, step, tailwind ('p-4', 'gap-3'), css ('16px'), working (the formula with its numbers) }. Call it for the padding of a box that holds content (a card, a section, a sheet or dialog body, a list row, an empty state) and the gaps inside it, working from the innermost box out. Never for a control's side padding (a button, input, chip, tab, nav or menu row): that is fixed per kind, see get_foundation spacing. A group with no border or fill gets no padding, only gaps.",
  input: {
    box: external_exports.enum(["text", "boxes", "gap-between-boxes", "gap-between-texts"]).describe(
      "What to work out: 'text' the padding of a box holding text (runs); 'boxes' the padding of a box holding boxes (children, and runs for any text of its own); 'gap-between-boxes' the gap between sibling boxes (children's padding); 'gap-between-texts' the gap between two texts (runs: [before, after], and pair)."
    ),
    runs: external_exports.array(run).optional().describe(
      "The box's texts, one entry per run of one size: [{ size: 13, lines: 2 }]. For 'gap-between-texts', exactly two: the text before the gap and the text after it."
    ),
    children: external_exports.array(child).optional().describe("The boxes inside, each with its padding (and size, for 'boxes')."),
    pair: external_exports.enum(["tight", "loose"]).optional().describe(
      "For 'gap-between-texts': 'tight' for two texts that belong together (a title and its subtitle, a label and its value, a figure and its caption), 'loose' between blocks."
    ),
    unit: external_exports.number().int().min(2).max(8).optional().describe(
      "The theme's spacing unit in px (its --spacing): 4 unless the theme says otherwise."
    )
  },
  annotations: readOnly,
  handle: ({ box, runs = [], children = [], pair, unit = 4 }) => {
    const params = spacingDefaults;
    const texts = runs.map(linesOf);
    let px3;
    let working;
    let prefix = "p";
    if (box === "text") {
      if (!texts.length)
        throw new ToolError(
          "box 'text' needs runs: [{ size, lines }] for each run of text."
        );
      const size = typeSize(texts);
      const lines = texts.reduce((sum, item) => sum + item.lines, 0);
      px3 = boxPadding({ runs: texts }, params);
      working = `${params.k} \xD7 ${one(size)}px \xD7 (1 + ${params.alpha}\xB7${log(lines)}) = ${one(px3)}px`;
    } else if (box === "boxes") {
      if (!children.length)
        throw new ToolError(
          "box 'boxes' needs children: [{ padding, size }] for each box inside."
        );
      const inner = children.map((item, index) => {
        if (item.size === void 0) {
          throw new ToolError(
            `children[${index}] needs size (its type size in px) for box 'boxes'.`
          );
        }
        return { padding: item.padding, size: item.size };
      });
      const all2 = [...texts, ...inner.map((item) => ({ size: item.size, lines: 1 }))];
      const size = typeSize(all2);
      const lines = all2.reduce((sum, item) => sum + item.lines, 0);
      const content = params.k * size * (1 + params.alpha * Math.log2(Math.max(1, lines)));
      const deepest = Math.max(...inner.map((item) => item.padding));
      px3 = boxPadding({ runs: texts, children: inner }, params);
      working = `max(${params.k} \xD7 ${one(size)}px \xD7 (1 + ${params.alpha}\xB7${log(lines)}) = ${one(content)}, ${params.nesting} \xD7 ${deepest} = ${one(deepest * params.nesting)}) = ${one(px3)}px`;
    } else if (box === "gap-between-boxes") {
      if (!children.length)
        throw new ToolError(
          "box 'gap-between-boxes' needs children: [{ padding }] for the sibling boxes."
        );
      const paddings = children.map((item) => item.padding);
      const deepest = Math.max(...paddings);
      px3 = boxGap(paddings, params);
      prefix = "gap";
      working = `${params.gapRatio} \xD7 ${deepest}px (the fullest sibling's padding) = ${one(px3)}px`;
    } else {
      const [before, after] = texts;
      if (texts.length !== 2 || !before || !after) {
        throw new ToolError(
          "box 'gap-between-texts' needs exactly two runs: the text before the gap, then the text after it."
        );
      }
      if (!pair)
        throw new ToolError(
          "box 'gap-between-texts' needs pair: 'tight' for two texts that belong together, 'loose' between blocks."
        );
      const ratio = pair === "tight" ? params.tight : params.loose;
      const around = before.lines + after.lines - 1;
      px3 = textGap({ before, after, pair: pair === "tight" }, params);
      prefix = "gap";
      working = `${after.size}px (the text after) \xD7 ${ratio} \xD7 (1 + ${params.beta}\xB7${log(around)}) = ${one(px3)}px`;
    }
    const capped = prefix === "p" && px3 >= params.cap ? ` (capped at ${params.cap}px)` : "";
    const step = snap(px3, unit);
    const snapped = step * unit;
    return structured({
      px: snapped,
      step,
      tailwind: `${prefix}-${step}`,
      css: `${snapped}px`,
      working: `${working}${capped} \u2192 ${prefix}-${step} (${snapped}px at a ${unit}px unit)`
    });
  }
});

// src/tools/get-tokens.ts
var getTokensTool = defineTool({
  name: "get_tokens",
  title: "Get tokens",
  description: `Returns Continuum's tokens (the role colours action, on-action, selected, tint, focus; the neutral, primary, success, warning and error ramps 50\u2013950; radii; type sizes with line heights; the two weights; control heights; the spacing unit; the font and tracking), in Tailwind's names, in one format:
- 'css': :root custom properties with values resolved, dark as [data-mode="dark"] overrides.
- 'tailwind': the app.css itself, the Tailwind v4 entry a React project uses (everything, charts included).
- 'json': { light: { 'color-neutral-50': '#f8f8f8', \u2026 }, dark: { only what differs } }.
- 'dtcg': W3C Design Tokens (Format Module 2025.10), colours in oklch with an sRGB hex fallback, as the text of two files: continuum.tokens.json (light, every token) and continuum.dark.tokens.json (only the colours dark changes), loaded in that order.
- 'paper': the payload for Paper's create_tokens (add the fileId), plus to_dark and to_light payloads for set_tokens, since Paper has no modes: switching the file's mode is one set_tokens call.
- 'figma': a use_figma script with the payload inside: one collection 'Continuum', modes Light and Dark, COLOR as 0\u20131 rgba, FLOAT in px, STRING for the family, names with slashes (color/neutral/200, radius/card, text/xs, size/control). Pass the script to use_figma as it is.
Call this once when setting up a design file or a non-React stack, before drawing or styling anything.`,
  input: {
    format: external_exports.enum(["css", "tailwind", "json", "dtcg", "paper", "figma"]).describe("The form to return the tokens in; see the description."),
    theme: themeArgument.optional(),
    mode: external_exports.enum(["light", "dark", "both"]).optional().describe("Which mode's values: 'light', 'dark', or 'both' (the default)."),
    include: external_exports.array(external_exports.enum(["charts", "widths"])).optional().describe(
      "Extra tokens: 'charts' the data colours chart-1\u20135 and chart-series-1\u20135; 'widths' the fixed widths of the sidebar, popover, menu, toast, dialog, sheet and so on. Left out unless asked."
    )
  },
  annotations: readOnly,
  handle: async ({ format, theme, mode = "both", include = [] }) => {
    const system = await loadSystem(theme).catch((cause) => {
      throw new ToolError(
        `Could not read the theme ${JSON.stringify(theme)}: ${cause instanceof Error ? cause.message : String(cause)}. Pass the path to the project's app.css, its contents, or leave theme empty for the default; create_theme writes one.`
      );
    });
    if (format === "tailwind") return text(system.css);
    const tokens4 = collectTokens(system, include);
    if (format === "css") return text(toCss3(system, tokens4, mode));
    if (format === "json") return structured({ theme: system.label, ...toJson(tokens4, mode) });
    if (format === "dtcg") return structured({ theme: system.label, ...toDtcg(tokens4, mode) });
    if (format === "paper") {
      return structured({
        theme: system.label,
        ...toPaper(tokens4, mode),
        note: "Call create_tokens with create_tokens.tokens and the file's fileId. set_tokens with to_dark.tokens turns every artboard in the file dark, to_light.tokens back; take each mode's screenshots in turn."
      });
    }
    return structured({ theme: system.label, ...toFigma(tokens4, mode) });
  }
});

// src/tools/list-components.ts
var listComponentsTool = defineTool({
  name: "list_components",
  title: "List components",
  description: "List every part of Continuum by group (App frame, Navigation, Actions, Inputs, Forms and settings, Filtering, Overlays, Content, Labels and identity, Status, Messages, AI, Charts), each with what it is for in one sentence. Call this first when composing a screen, to see the parts before drawing or writing any; then get_component for each part you use. Names joined by ' \xB7 ' are one entry (a part and its pieces).",
  input: {
    group: external_exports.string().optional().describe(
      "Only this group, by name or the start of it: 'Inputs', 'overlays', 'ai'. Leave empty for all."
    )
  },
  annotations: readOnly,
  handle: ({ group }) => {
    const all2 = listComponents();
    const names = [...new Set(all2.map((each) => each.group))];
    const wanted = group?.trim().toLowerCase();
    const picked = wanted ? names.filter((name2) => name2.toLowerCase().startsWith(wanted)) : names;
    if (picked.length === 0) {
      throw new ToolError(
        `No group named "${group}". The groups are: ${names.join(", ")}. Or leave group empty for all.`
      );
    }
    return structured({
      groups: picked.map((name2) => ({
        group: name2,
        components: all2.filter((each) => each.group === name2).map(({ name: name3, summary }) => ({ name: name3, summary }))
      }))
    });
  }
});

// src/server.ts
var name = "Continuum";
var version2 = "0.1.0";
var instructions = `
Continuum is a design system for quiet, dense tool UI: 13px type in two weights (400, 500), 1px hairline borders, one action colour, almost no shadow, controls 34 or 38 high, corners chip 6 \xB7 item 10 \xB7 control 12 \xB7 card 16 \xB7 panel 20, a 4px spacing scale, light and dark. Every rule is stated in units, so it applies in React (where it ships as a component library), Angular, Vue, plain CSS, Qt and on a design canvas (Paper, Figma) alike.

Building: name the screen's kind and read its anatomy with get_page_kind (overview, index, detail, create or edit, settings, assistant, sign in). Compose from the parts: list_components, then get_component for each part's spec, values and states, written for your medium. find_pattern answers "how do I build a filter bar, a KPI row, an empty state". get_foundation gives the values of one topic (colour, type, radius, spacing, heights, layout \u2026). get_spacing works out a box's padding and gaps from what it holds; get_tokens gives the token set as CSS, Tailwind, DTCG JSON, or a Paper or Figma payload.

Improving existing UI: audit_source reads source files (React, Angular, Vue, Svelte, HTML, CSS, SCSS) and audit_ui reads a rendered tree of boxes, from a browser (run get_snapshot_script in the page and pass its result) or a canvas (Paper's computed styles). Both return findings: what is off, in units, what Continuum wants, why, and the fix written for the stack. Apply 'fix' findings of high confidence; apply medium ones and look; ask about low ones; propose 'advise' findings (structure: two primary actions, tabs that belong in the dock, nested containers) to the person before changing them. Audit again until it is clean, then look at the result in light and dark.

Theming: create_theme turns options (accent, greys, font, type size, spacing unit, control size, corners) into the app.css and DESIGN.md a project uses; check_theme measures its contrast. Contrast checks advise: the person's eye decides. Pass a project's app.css as theme to the other tools to check against its own values.

The prompts build_screen, improve_ui and review_canvas run these as a procedure.
`.trim();
var tools = [
  listComponentsTool,
  getComponentTool,
  findPatternTool,
  getPageKindTool,
  getFoundationTool,
  getSpacingTool,
  getTokensTool,
  getSnapshotScriptTool,
  auditUiTool,
  auditSourceTool,
  createThemeTool,
  checkThemeTool
];
var prompts = [buildScreenPrompt, improveUiPrompt, reviewCanvasPrompt];
var createServer = () => {
  const server = new McpServer({ name, version: version2 }, { instructions });
  for (const tool of tools) registerTool(server, tool);
  for (const prompt of prompts) registerPrompt(server, prompt);
  return server;
};
var isMain = process.argv[1] && import.meta.url.endsWith(process.argv[1].replace(/\\/g, "/").split("/").pop() ?? "");
if (isMain) {
  await createServer().connect(new StdioServerTransport());
}
export {
  createServer,
  instructions,
  name,
  prompts,
  tools,
  version2 as version
};
